import { useState, useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';
import { useResizeObserver } from './shared/useResizeObserver';
import { paletteNB } from './shared/naive-bayes';

// =============================================================================
// DvGCrossoverPlot — §7.4 companion. Loads the precomputed sweep at
//   /sample-data/naive-bayes/dvg_crossover.json
// (generated by notebooks/naive-bayes/precompute_dvg_crossover.py) and renders
// learning curves for Gaussian NB and logistic regression at three feature
// counts d ∈ {10, 50, 200} with n_reps = 50 per (n, d) cell.
//
// The crossover is most visible at d = 200: LR wins at very small n where its
// regularization-free fit hasn't yet over-parameterized, GNB takes over once
// n ≳ d/log(d), and both converge toward the Bayes-error floor at large n.
// =============================================================================

interface DvGPayload {
  seed: number;
  d_values: number[];
  n_values: number[];
  n_reps: number;
  results: {
    gaussianNB: Record<string, Array<{ n: number; mean_err: number; se_err: number }>>;
    logisticRegression: Record<string, Array<{ n: number; mean_err: number; se_err: number }>>;
  };
}

export default function DvGCrossoverPlot() {
  const { ref: containerRef, width } = useResizeObserver<HTMLDivElement>();
  const [payload, setPayload] = useState<DvGPayload | null>(null);
  const [selectedD, setSelectedD] = useState<number>(200);
  const [showError, setShowError] = useState<string | null>(null);
  const svgRef = useRef<SVGSVGElement | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch('/sample-data/naive-bayes/dvg_crossover.json')
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((j: DvGPayload) => {
        if (!cancelled) {
          setPayload(j);
          setSelectedD(j.d_values[j.d_values.length - 1]);
        }
      })
      .catch((e) => {
        if (!cancelled) setShowError(String(e));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const W = Math.max(360, Math.min(width || 720, 720));
  const H = 360;
  const margin = { top: 14, right: 20, bottom: 40, left: 50 };
  const innerW = W - margin.left - margin.right;
  const innerH = H - margin.top - margin.bottom;

  const curves = useMemo(() => {
    if (!payload) return null;
    const key = String(selectedD);
    return {
      gnb: payload.results.gaussianNB[key],
      lr: payload.results.logisticRegression[key],
    };
  }, [payload, selectedD]);

  useEffect(() => {
    if (!svgRef.current || !curves || !payload) return;
    const svg = d3.select(svgRef.current);
    svg.attr('viewBox', `0 0 ${W} ${H}`).selectAll('*').remove();
    const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`);

    const allMeans = [...curves.gnb, ...curves.lr].map((r) => r.mean_err);
    const allSes = [...curves.gnb, ...curves.lr].map((r) => r.se_err);
    const yMax = Math.min(0.55, Math.max(...allMeans) + Math.max(...allSes) + 0.02);
    const yMin = Math.max(0, Math.min(...allMeans) - Math.max(...allSes) - 0.01);

    const x = d3.scaleLog().domain([payload.n_values[0], payload.n_values[payload.n_values.length - 1]]).range([0, innerW]);
    const y = d3.scaleLinear().domain([yMin, yMax]).range([innerH, 0]);

    g.append('g').attr('transform', `translate(0,${innerH})`).call(d3.axisBottom(x).ticks(7, '~g'));
    g.append('g').call(d3.axisLeft(y).ticks(6));

    g.append('text')
      .attr('x', innerW / 2)
      .attr('y', innerH + 32)
      .attr('text-anchor', 'middle')
      .attr('font-size', 12)
      .style('fill', 'currentColor')
      .text('Training size n (log scale)');
    g.append('text')
      .attr('transform', `translate(-36,${innerH / 2}) rotate(-90)`)
      .attr('text-anchor', 'middle')
      .attr('font-size', 12)
      .style('fill', 'currentColor')
      .text('Test error');

    const drawSeries = (
      series: Array<{ n: number; mean_err: number; se_err: number }>,
      color: string,
      label: string,
    ) => {
      const line = d3
        .line<typeof series[number]>()
        .x((d) => x(d.n))
        .y((d) => y(d.mean_err));
      g.append('path')
        .datum(series)
        .attr('fill', 'none')
        .attr('stroke-width', 2)
        .attr('d', line)
        .style('stroke', color);
      g.append('g')
        .selectAll('line.err')
        .data(series)
        .join('line')
        .attr('class', 'err')
        .attr('x1', (d) => x(d.n))
        .attr('x2', (d) => x(d.n))
        .attr('y1', (d) => y(d.mean_err - d.se_err))
        .attr('y2', (d) => y(d.mean_err + d.se_err))
        .attr('stroke-width', 1)
        .attr('opacity', 0.7)
        .style('stroke', color);
      g.append('g')
        .selectAll('circle')
        .data(series)
        .join('circle')
        .attr('cx', (d) => x(d.n))
        .attr('cy', (d) => y(d.mean_err))
        .attr('r', 3.5)
        .style('fill', color);
      void label;
    };

    drawSeries(curves.gnb, paletteNB.pos, 'Gaussian NB');
    drawSeries(curves.lr, paletteNB.neg, 'Logistic regression');

    // Legend.
    const legend = g.append('g').attr('transform', `translate(${innerW - 165},6)`);
    [
      { label: 'Gaussian NB (generative)', color: paletteNB.pos },
      { label: 'Logistic reg (discriminative)', color: paletteNB.neg },
    ].forEach((item, i) => {
      legend
        .append('rect')
        .attr('x', 0)
        .attr('y', i * 16 - 9)
        .attr('width', 14)
        .attr('height', 3)
        .style('fill', item.color);
      legend
        .append('text')
        .attr('x', 18)
        .attr('y', i * 16)
        .attr('font-size', 11)
        .style('fill', 'currentColor')
        .text(item.label);
    });
  }, [curves, payload, W, H, innerW, innerH, margin.left, margin.top]);

  return (
    <div ref={containerRef} className="not-prose my-6">
      <div className="flex flex-wrap items-center gap-3 mb-2 text-sm">
        <span>Feature dimension d:</span>
        {payload ? (
          payload.d_values.map((d) => (
            <button
              key={d}
              onClick={() => setSelectedD(d)}
              className={`px-3 py-1 rounded border text-xs ${selectedD === d ? 'font-semibold' : 'opacity-70'}`}
              aria-pressed={selectedD === d}
              style={selectedD === d ? { background: paletteNB.highlight, color: 'white' } : undefined}
            >
              d = {d}
            </button>
          ))
        ) : (
          <span className="opacity-50">loading...</span>
        )}
      </div>
      {showError ? (
        <div className="text-sm" style={{ color: paletteNB.neg }}>
          Failed to load /sample-data/naive-bayes/dvg_crossover.json: {showError}
        </div>
      ) : !payload ? (
        <div className="text-sm opacity-60" style={{ minHeight: H }}>Loading Ng–Jordan sweep...</div>
      ) : (
        <svg ref={svgRef} className="w-full" style={{ maxHeight: H }} role="img" aria-label={`Ng-Jordan learning curves at d = ${selectedD}`}/>
      )}
      {payload && (
        <div className="text-xs opacity-75 mt-1 text-center">
          Each point averages {payload.n_reps} replicates. The crossover is most visible at d = 200,
          where GNB's O(log d / n) rate beats LR's O(d / n) over the small-to-mid sample range.
        </div>
      )}
    </div>
  );
}
